link.script:
    //
    <!--   

    jQuery(function() {      

      // State Specific Text
      //-------------------------------------------------
      //jQuery("#statewide_tx").hide();

      // Toggle the statewide text with class
      jQuery(".statewide_tx_header_div").click(function() {
             jQuery(this).next("#statewide_tx").slideToggle(500);

             var divText = jQuery(".statewide_tx_header_div").html();

             if (divText.indexOf('Click for') != -1) {
               //jQuery(".statewide_tx_header_div span").replaceWith( "<span id='statewide_header_tx'>Click to hide state-specific text</span>" );

               jQuery("#statewide_header_tx").replaceWith( "<span id='statewide_header_tx'>Click to hide state-specific text</span>" );

               jQuery("#collapsingIcon").removeClass('ui-icon-circle-plus');
               jQuery("#collapsingIcon").addClass('ui-icon-circle-minus');

             } else {
               //jQuery(".statewide_tx_header_div span").replaceWith( "<span id='statewide_header_tx'>Click for state-specific text</span>" );

               jQuery("#statewide_header_tx").replaceWith( "<span id='statewide_header_tx'>Click for state-specific text</span>" );

               jQuery("#collapsingIcon").removeClass('ui-icon-circle-minus');
               jQuery("#collapsingIcon").addClass('ui-icon-circle-plus');
             }

      });

      // News Text
      //-------------------------------------------------
      //jQuery("#news_tx").hide();

      // Toggle the news text with class
      jQuery("#news_header").click(function() {
             jQuery(this).next("#news_tx").slideToggle(500);

             var divText = jQuery("#news_header").html();

             if (divText.indexOf('Click for') != -1) {

               jQuery("#news_header_tx").replaceWith( "<span id='news_header_tx'>Click to hide</span>" );

               jQuery("#collapsingNewsIcon").removeClass('ui-icon-circle-plus');
               jQuery("#collapsingNewsIcon").addClass('ui-icon-circle-minus');

               jQuery("#news_header").removeClass('news_tx_header_div');
               jQuery("#news_header").addClass('news_tx_header_div_expanded');

             } else {

               jQuery("#news_header_tx").replaceWith( "<span id='news_header_tx'>Click for</span>" );

               jQuery("#collapsingNewsIcon").removeClass('ui-icon-circle-minus');
               jQuery("#collapsingNewsIcon").addClass('ui-icon-circle-plus');

               jQuery("#news_header").removeClass('news_tx_header_div_expanded');
               jQuery("#news_header").addClass('news_tx_header_div');
             }

      });

      // Station Text
      //-------------------------------------------------
      //jQuery("#station_tx").hide();

      // Toggle the station text with class
      jQuery("#station_header").click(function() {
             jQuery(this).next("#station_tx").slideToggle(500);

             var divText = jQuery("#station_header").html();

             if (divText.indexOf('Click for') != -1) {

               jQuery("#station_header_tx").replaceWith( "<span id='station_header_tx'>Click to hide</span>" );

               jQuery("#collapsingStationIcon").removeClass('ui-icon-circle-plus');
               jQuery("#collapsingStationIcon").addClass('ui-icon-circle-minus');

             } else {

               jQuery("#station_header_tx").replaceWith( "<span id='station_header_tx'>Click for</span>" );

               jQuery("#collapsingStationIcon").removeClass('ui-icon-circle-minus');
               jQuery("#collapsingStationIcon").addClass('ui-icon-circle-plus');

             }

      });  

      // Round corners on html5 button using only css (IE version 8 and lower need extra help)
      //-------------------------------------------------
      if (!Modernizr.borderradius) {
            jQuery.getScript("/nwisweb/javascripts/jquery.corner.js", function() {
              jQuery(".btn").corner();
              jQuery(".mapperbtn").corner();
            });
      }

      // If User selects the output sites to map option, force xml
      //-------------------------------------------------
      jQuery("input[type=radio][value=nwis_mapper]").change(function(){
          //alert("Output sites on a map radio was selected");          
          jQuery("#sitefile_output_format").val("xml");          
      });      

      // If User selects a file as search criteria, disable the output sites to map option.
      //-------------------------------------------------
      if ( jQuery("#site_no_file_attachment").length || jQuery("#parameter_cd_file_attachment").length ) {
         //jQuery("#nwis_mapper").attr('disabled', true);
         jQuery("input[type=radio][value=nwis_mapper]").attr("disabled",true);

         jQuery('#label_nwis_mapper').css({ opacity: 0.4 });
         jQuery('div[id^="label_"]').css({ display: "inline" });

         jQuery("#fileOfSitesMsg").append("* Selecting this search criteria disables the Show sites on a map option which is currently incompatible with file attachments.");
         jQuery("#fileOfPmCodesMsg").append("* Selecting this search criteria disables the Show sites on a map option which is currently incompatible with file attachments.");
      } else {
         //jQuery("#nwis_mapper").attr('disabled', false);
         jQuery("input[type=radio][value=nwis_mapper]").attr("disabled",false);
         jQuery('div[id^="label_"]').css({ display: "inline" });
      }

      // Plone Help
      //-------------------------------------------------

      var ploneHelpURL = "https://help.waterdata.usgs.gov";
      //alert("ploneHelp from conf:" + ploneHelpURL);

      // Testing qTip, a jQuery plug-in for ToolTips
      // Match all <A/> links with a title tag and use it as the rollover content (default).
      // -------------------------------------------------
      jQuery('a[title]').qtip();

      // Finds all <a href's with ids. If an id exists,
      // run a get request into Plone, find the div with the same id,
      // and update the title attribute so hover will populate with Plone info
      // -------------------------------------------------

      jQuery('a').each(function(){
           var thisID       = jQuery(this).attr('id');
           var thisHREF     = jQuery(this).attr('href');

           var getTextFromPlone;
           var partialPloneURL;
           var pageInPloneUsingProxy;

           // Search href so help data are retrieved from appropriate plone page
           if (thisHREF && thisID) {
               //alert("thisID:" + thisID + " thisHREF:" + thisHREF);

               // Looking for Plone or help.waterdata.usgs.gov in URL - basically only help links
               getTextFromPlone = thisHREF.indexOf("/Plone/");
               if (getTextFromPlone > -1) {
                  // Get URL string after /Plone/
                  partialPloneURL = thisHREF.split('/Plone/')[1];
                  pageInPloneUsingProxy = 'https://waterdata.usgs.gov/exthelp/' + partialPloneURL;
               }

               //getTextFromPlone = thisHREF.indexOf("/help.waterdata.usgs.gov/");
               //if (getTextFromPlone > -1) {
                   // Get URL string after /help.waterdata.usgs.gov/
               //    partialPloneURL = thisHREF.split('/help.waterdata.usgs.gov/')[1];
               //    pageInPloneUsingProxy = 'https://waterdata.usgs.gov/exthelp/' + partialPloneURL;
               //}

               // Pull Plone URL from Conf file
               // ---------------------------------------------
               getTextFromPlone = thisHREF.indexOf(ploneHelpURL);
               if (getTextFromPlone > -1) {
                   // Get URL string after /help.waterdata.usgs.gov/
                   partialPloneURL = thisHREF.split(ploneHelpURL)[1];
                   pageInPloneUsingProxy = 'https://waterdata.usgs.gov/exthelp/' + partialPloneURL;
               }

           }

           if (thisID) {
               //alert("Testing finding <a href's with IDs = " + thisID + " URL = " + thisHREF + " pageInPloneUsingProxy = " + pageInPloneUsingProxy);

              var origTitle = jQuery('#'+thisID).attr("title");

              jQuery('#'+thisID).mouseover(function (e) {

                 //var getURL = "http://webvadevvs03.er.usgs.gov/exthelp/codes-and-parameters/codes";
                 var getURL = pageInPloneUsingProxy;

                 var origTitlePlusData = '';
                 var hrefValuesList = [];
                 var host = 'https://waterdata.usgs.gov';

                 jQuery.ajax({

                   url: getURL,
                   dataType: "html",
                   success: function (data) {
                      var data          = jQuery(data).find('.'+thisID);
                      var ref, ref_mod, internalRef, anchors, i, end, data_new;

                      // Search text returned from Plone for hrefs
                      anchors = data.find('a');

                      // Loop through all href values from each anchor element
                      // Use this to search and replace text returned from Plone to replace internal links with ploneHelpURL
                      end      = anchors.length;
                      data_new = data.html();
                      var seen = {};
                      for (i = 0; i < end; i++) { 
                         ref         = anchors[ i ].href ;
                         ref_mod     = ref.replace('https://waterdata.usgs.gov',ploneHelpURL);                                                 			 
                         internalRef = ref.replace('https://waterdata.usgs.gov', '');
                         internalRef = internalRef.replace('&', '&amp;');

                         var txt = internalRef;
                         if (seen[txt]) {
                            // Do not replace same internal link twice
                         } else {
                            seen[txt] = true;

                            //var regex = new RegExp('{'+internalRef+'}', "ig");      // Global replace efforts not working
                            //var regex = new RegExp(internalRef, "g");                                           
                            //data_new = data_new.replace(regex,ref_mod);

                            data_new = data_new.replace(internalRef,ref_mod);        // This works, but does not do global replace
                                                                                     // This solution cannot have duplicate internal links per hover in Plone

                            //data_new = data_new.split(internalRef).join(ref_mod);  // This works global, but doubles up

                            //alert(" Changed: " + internalRef + " to " + ref_mod + " ---->  data_new: " + data_new );			                                
                            hrefValuesList.push( ref );
                         }
                      }

                      //alert("data: " + data_new );

                      // Combine text from Plone to original title
                      //origTitlePlusData = origTitle + ' <BR><BR> ' + data.html();                      
                      origTitlePlusData = origTitle + ' <BR><BR> ' + data_new;

                      if (data.html() != null) {
                         jQuery('#'+thisID).attr('title', origTitlePlusData);
                      }
                   }
                 });
              });

 	      // Makes the ToolTip delay so that you can click on a URL in the help text
 	      jQuery(this).qtip({
 		 hide: {
 		    delay:500, // Give a small delay to allow the user to mouse over it
 		    fixed:true
 		 },
 		 style: {
 		    name: 'dark',
 		    style: {
 		       border: 1,
 		       cursor: 'pointer',
 		       padding: '5px 8px',
 		       name: 'blue'
 		    },
 		 border: {},
 		 tip: true     // Apply a tip at the default tooltip corner
 		 }
 	      });


           } // End of -> if(thisID)
      });   // End of -> each function




      // Processing Bar
      //-------------------------------------------------
      // If the loading bar exists, remove it

      var barChk = jQuery(".loading").text();
      //alert('loading=' + barChk);

      if (barChk) {
         jQuery(document).ready(function() {   
             processingBar.hideBar();
             jQuery("#loading").fadeOut("slow",function() { jQuery("#loading").remove(); });
         });
      }   

      // Select All, Unselect All Available Parameters toggle
      //-----------------------------------------------------
      jQuery("#all_available_parameters").click(function(){
         if(this.checked){
            jQuery('input[type=checkbox]').each(function(){
               jQuery(".available_parameters").prop('checked', true);
            })
         }else{
            jQuery('input[type=checkbox]').each(function(){
               jQuery(".available_parameters").prop('checked', false);
            })
         }
      });            

      // DatePicker
      //-------------------------------------------------
      // Not needed

     // TableSorter - New Version with Fixed Headers
     //-------------------------------------------------
          //jQuery("table").tablesorter({
     jQuery(".dataList").tablesorter({
            //selectorHeaders: '> thead th, > thead td',
            //widthFixed : true,
	    headerTemplate : '{content} {icon}', // Add icon for jui theme; new in v2.7!
	    widgets: ["columns", "filter", "stickyHeaders", "uitheme", "zebra"] ,
	    //sortList: [ [0,0], [1,0], [2,0] ],   // Sorts on first 3 cols
	    widgetOptions: {
	      // css class name applied to the sticky header row (tr)
	      stickyHeaders : 'tablesorter-stickyHeader',
	      zebra   : ["ui-widget-content even", "ui-state-default odd"],
	      uitheme : 'jui'
	    }
     });

     // Exception for data tables using superscripts 
     // (peaks and uv use this now)
     //-------------------------------------------------
     jQuery(".dataListWithSuperscript").tablesorter({
        headerTemplate : '{content} {icon}', // Add icon for jui theme; new in v2.7!
        widgets: ["columns", "filter", "stickyHeaders", "uitheme", "zebra"] ,
        widgetOptions: {
           // css class name applied to the sticky header row (tr)
           stickyHeaders : 'tablesorter-stickyHeader',
           zebra   : ["ui-widget-content even", "ui-state-default odd"],
           uitheme : 'jui'
        },
        textExtraction: function(node) {
           // Any columns that have a span tag, sort only on span tag content, ignoring sup (superscript) tag
           if (jQuery(node).find('span').text() != "") {
              var selected = jQuery(node).find("span").text();
              return selected;
           } else {
              return jQuery(node).text();
           }
        }		   	   
     });

     // Click a row and it will highlight for greater visibility
     //-------------------------------------------------
     jQuery('.dataList td').click(
           	function (event) { jQuery(this).parent('tr').toggleClass('rowclick');
     });

     // Click a row and it will highlight for greater visibility
     //-------------------------------------------------
     jQuery('.dataListWithSuperscript td').click(
           	function (event) { jQuery(this).parent('tr').toggleClass('rowclick');
     });


     // Water-Use
     //-------------------------------------------------

    // Testing whether this fixes a PR where the category select box
    // is not wide enough in IE 9
    jQuery("#wu_category").css("width", "auto");
    jQuery("#wu_category").css("overflow", "auto");

    var http_text  = window.location.href;
    //alert(http_text);

    var wu_search = http_text.search(/water_use/i);
    //alert(wu_search);

    if (wu_search != '-1') {

      //alert("Only executing wateruse jquery code on wateruse pages...");

      //-------------------------------------------------
      // Check for county var in URL
      jQuery.extend({
        getUrlVars: function(){
          var vars = [], hash;
          var hashes = window.location.href.slice(window.location.href.indexOf('?') + 1).split('&');
          for(var i = 0; i < hashes.length; i++) {
            hash = hashes[i].split('=');
            vars.push(hash[0]);
            vars[hash[0]] = hash[1];
          }
        return vars;
        },
        getUrlVar: function(name){
          return jQuery.getUrlVars()[name];
        }
      });

      //-------------------------------------------------
      // Getting URL var by its name - wu_county_nms
      var countyNames = jQuery.getUrlVar('wu_county_nms');
      //console.log('countyNames...' + countyNames);      

      // If wu_county_nms are in the URL pass it again as 
      // hidden input var so the data tables have access to it
      if(countyNames){        
	jQuery('<input>').attr({
	  type: 'hidden',
	  id: 'wu_county_nms',
	  name: 'wu_county_nms',
	  value: countyNames
	}).appendTo('#select_sites_data')
      }           
      //-------------------------------------------------

      // Getting URL var by its name - wu_category_nms
      var categoryNames = jQuery.getUrlVar('wu_category_nms');
      var pattCategory  = /[()]/g;
      if(typeof categoryNames !== "undefined")
        {
         categoryNames.replace(pattCategory, '');
        }

      // If wu_category_nms are in the URL pass it again as 
      // hidden input var so the data tables have access to it
      if(categoryNames){
	jQuery('<input>').attr({
	  type: 'hidden',
	  id: 'wu_category_nms',
	  name: 'wu_category_nms',
	  value: categoryNames
	}).appendTo('#select_sites_data')
      }           
      //-------------------------------------------------  
      // Clear selections on all boxes to start
      jQuery("#wu_year option:selected").removeAttr("selected");
      jQuery("#wu_area option:selected").removeAttr("selected");
      jQuery("#wu_county option:selected").removeAttr("selected");
      jQuery("#wu_category option:selected").removeAttr("selected");

      // Hide Area, County, and Category boxes to start
      jQuery('#wu_area').hide();
      jQuery('#wu_county').hide();
      jQuery('#wu_category').hide(); 

      //-------------------------------------------------

      jQuery('#wu_year').bind('change blur',function() {

         //alert('Handler for Water Use Year called...');
         var state  = jQuery( "#office" ).val();
         var year   = jQuery( "#wu_year" ).val();
         var area   = jQuery( "#wu_area" ).val();
         var county = jQuery( "#wu_county" ).val();
         //alert('state: ' + state);

         if (year) {
            //alert("Year was selected..." + year );
            if (state == "usa") {
               jQuery('#wu_category').show();
            } else {
               jQuery('#wu_area').show();
               jQuery('#wu_category').hide();
            }

            if (area == "State Total") {
               jQuery('#wu_category').show();
            }
            if ( jQuery('#wu_county') ) {
		      //alert("Need to update County list " + "https://waterdata.usgs.gov/" + state + "/nwis/water_use/?format=updateCounties");

		      // Replace select box with Loading... while get request performs
		      jQuery('#wu_county').find('option').remove().end();
		      jQuery('#wu_county').append("<option >Loading...</option>");
		      jQuery('#wu_category').find('option').remove().end();
		      jQuery('#wu_category').append("<option >Loading...</option>");

		      jQuery.get(
				   "https://waterdata.usgs.gov/" + state + "/nwis/water_use",
				   "format=updateCounties&wu_year="+year+"&wu_area="+area,
				   function(data) {
						   //alert(data);
						   jQuery('#wu_county').find('option').remove().end();
						   jQuery('#wu_county').append(data);
						   return false;
						  },
				   "text"
				  );
		      //alert("Need to update Category list " + "https://waterdata.usgs.gov/" + state + "/nwis/water_use/?format=updateCategories");
		      jQuery.get(
				   "https://waterdata.usgs.gov/" + state + "/nwis/water_use",
				   "format=updateCategories&wu_year="+year+"&wu_area="+area+"&wu_county="+county,
				   function(data) {
						   //alert(data);
						   jQuery('#wu_category').find('option').remove().end();
						   jQuery('#wu_category').append(data);
						   return false;
						  },
				   "text"
				  );
            }

         } else {  // if year has no value
            document.select_sites_data.wu_area.value = '';
            document.select_sites_data.wu_county.value = '';
            document.select_sites_data.wu_category.value = '';
            jQuery('#wu_area').hide();
            jQuery('#wu_county').hide();
            jQuery('#wu_category').hide();
         }

      });
      //-------------------------------------------------

      jQuery('#wu_area').bind('change blur',function() {

         //alert('Handler for Water Use Area Type called...');
         var state    = jQuery( "#office" ).val();
         var year     = jQuery( "#wu_year" ).val();
         var area     = jQuery( "#wu_area" ).val();
         var county   = jQuery( "#wu_county" ).val();
         //alert('Area: ' + area);

         if (area == 'County') {
            //alert("County was selected...create a county box based on the state: " + state);
            jQuery('#wu_county').show();
            jQuery('#wu_category').hide();
         } else {
            jQuery('#wu_county').hide();
		      //alert("Need to update Category list " + "https://waterdata.usgs.gov/" + state + "/nwis/water_use/?format=updateCategories");

		      // Replace select box with Loading... while get request performs
		      jQuery('#wu_category').find('option').remove().end();
		      jQuery('#wu_category').append("<option >Loading...</option>");

		      jQuery.get(
				   "https://waterdata.usgs.gov/" + state + "/nwis/water_use",
				   "format=updateCategories&wu_year="+year+"&wu_area="+area+"&wu_county="+county,
				   function(data) {
						   //alert(data);
						   jQuery('#wu_category').find('option').remove().end();
						   jQuery('#wu_category').append(data);
						   return false;
						  },
				   "text"
				  );
            jQuery('#wu_category').show();
         }
      });
      //-------------------------------------------------

      jQuery('#wu_county').bind('change blur',function() {

         //alert('Handler for Water Use County called...');
         var state  = jQuery( "#office" ).val();
         var year   = jQuery( "#wu_year" ).val();
         var area   = jQuery( "#wu_area" ).val();
         var county = jQuery( "#wu_county" ).val();

         if (year && area == 'County') {

		      //alert("Need to update Category list " + "https://waterdata.usgs.gov/" + state + "/nwis/water_use/?format=updateCategories");

		      // Replace select box with Loading... while get request performs
		      jQuery('#wu_category').find('option').remove().end();
		      jQuery('#wu_category').append("<option >Loading...</option>");

		      jQuery.get(
				   "https://waterdata.usgs.gov/" + state + "/nwis/water_use",
				   "format=updateCategories&wu_year="+year+"&wu_area="+area+"&wu_county="+county,
				   function(data) {
						   //alert(data);
						   jQuery('#wu_category').find('option').remove().end();
						   jQuery('#wu_category').append(data);
						   return false;
						  },
				   "text"
				  );
         }
         jQuery('#wu_category').show();

         if (!county) {  // if county has no value
            jQuery('#wu_category').hide();
         }

		 // Pass county names as a hidden input var.
		 // Create input var on the fly inside of above onchange county function.
		 // --------------------------------------------- 
		 // Create hidden input var if doesn't already exist
		    if(!jQuery('#wu_county_nms').length){
			jQuery('<input>').attr({
			  type: 'hidden',
			  id: 'wu_county_nms',
			  name: 'wu_county_nms'
			}).appendTo('#select_sites_data')
		    }

		 // Assign selected county names to hidden input var
		    var countyValues = [];
		    jQuery('#wu_county option:selected').each(function(index, value) {
		       var cleanValue = jQuery(value).text();
		       cleanValue = cleanValue.replace(/'/g,"");
		       countyValues[index] = cleanValue;
		       //alert('countyValues = ' + countyValues[index]);                             
		    });     
		    jQuery('input[id=wu_county_nms]').val(countyValues); 
		 // ---------------------------------------------

      }); // end of county onchange
      //-------------------------------------------------

      jQuery('#wu_source').bind('change blur',function() {

         //alert('Handler for Water Use Source called...');
         var state  = jQuery( "#office" ).val();
         var year   = jQuery( "#wu_year" ).val();
         var area   = jQuery( "#wu_area" ).val();
         var county = jQuery( "#wu_county" ).val();
         var source = jQuery( "#wu_source" ).val();

         if (source) {
		      //alert("Need to update Category list " + "https://waterdata.usgs.gov/" + state + "/nwis/water_use/?format=updateCategories");

		      // Replace select box with Loading... while get request performs
		      jQuery('#wu_category').find('option').remove().end();
		      jQuery('#wu_category').append("<option >Loading...</option>");

		      jQuery.get(
				   "https://waterdata.usgs.gov/" + state + "/nwis/water_use",
				   "format=updateCategories&wu_year="+year+"&wu_area="+area+"&wu_county="+county,
				   function(data) {
						   //alert(data);
						   jQuery('#wu_category').find('option').remove().end();
						   jQuery('#wu_category').append(data);
						   return false;
						  },
				   "text"
				  );
            jQuery('#wu_category').show();
         } else {
            jQuery('#wu_category').hide();
         }
      });
      //-------------------------------------------------   

      jQuery('#wu_category').bind('change blur',function() {

         //console.log("Changing wu_category ");
         var pattCategory = /[()]/g;

		 // Pass category names as a hidden input var.
		 // Create input var on the fly inside of above onchange category function.
		 // --------------------------------------------- 
		 // Create hidden input var if doesn't already exist
		    if(!jQuery('#wu_category_nms').length){
			jQuery('<input>').attr({
			  type: 'hidden',
			  id: 'wu_category_nms',
			  name: 'wu_category_nms'
			}).appendTo('#select_sites_data')
		    }

		 // Assign selected category names to hidden input var
		    var categoryValues = [];
		    jQuery('#wu_category option:selected').each(function(index, value) {
             var wu_category_nms = jQuery(value).text();
             //console.log("Clean wu_category_nms " + wu_category_nms);
		       categoryValues[index] = wu_category_nms.replace(pattCategory, '');
             //console.log("Clean wu_category_nms " + categoryValues[index]);
		       //alert('categoryValues = ' + categoryValues[index]);                             
		    });     
		    jQuery('input[id=wu_category_nms]').val(categoryValues); 
		 // ---------------------------------------------      

      });  
      //------------------------------------------------- 

      // Table Sorter for Water-Use HTML table
      //-------------------------------------------------
      var state   = jQuery( "#office" ).val();
      //alert('state...' + state);

      // Getting URL var by its name
      var countyVar = jQuery.getUrlVar('wu_county');
      //alert('wu_county...' + countyVar);

      // Set default sorts for National, County and State HTML outputs
      if (state == "usa") {
        //jQuery("#waterUseHTMLOutput").tablesorter( {sortList: [ [0,0] ] } ); // Sorts on first col
        jQuery("#waterUseHTMLOutput").tablesorter( {sortList: [ ] } );         // No default sort so customized national sort can default
      } else if (countyVar) {
        jQuery("#waterUseHTMLOutput").tablesorter( {sortList: [ [0,0], [1,0], [2,0], [3,0], [4,0] ] } );  // Sorts on first 5 cols
      } else {
        jQuery("#waterUseHTMLOutput").tablesorter( {sortList: [ [0,0], [1,0], [2,0] ] } ); // Sorts on first 3 cols
      }

      jQuery("#waterUseLegend").tablesorter( {sortList: [ [0,0] ] } ); // Sorts Legend on first col

      // Could use this to disable sort from certain cols if needed
      //jQuery("#waterUseHTMLOutput").tablesorter({headers: { 3:{sorter: false}, 4:{sorter: false}}});


    } // end if -> if (wu_search != '-1')


   });

   // -->
   //

div.script:
//
<!--

function server_level_navigation_manager()
 {
 var local_cgi_url_base = "/nwis";
 var national_host_url  = "";
 var nwis_mapper_url    = "https://maps.waterdata.usgs.gov/";
 //alert(national_host_url);
 var office_index  = document.select_office.office.selectedIndex;
 var office  = document.select_office.office.options[ office_index ].value;
 var my_office = "usa";
 if(office == my_office) {
   var url = local_cgi_url_base + '/'; }
 else {
   var url = national_host_url + '/' + office + "/nwis/"; }
 var program_index = document.select_office.program.selectedIndex;
 var program = document.select_office.program.options[ program_index ].value;

 if (program == 'mapper') {
   if (office != 'usa') {
     //var url = nwis_mapper_url + '?state=' + office ;
     var url = nwis_mapper_url + 'mapper/index.html?state=' + office; }
   else {
     var url = nwis_mapper_url ; }
     //window.open(url);
     window.location = (url); }

 else if(program == 'revision'){
    var url = url + 'si';
    //alert("url " + url);
    window.location = (url); } 

 else {
   var url = url + program;
   window.location = (url);}
 return (false);
 }
//-->
//

