<!--
function clear_form_elements(ele){

  jQuery(ele).find(':input').each(function() {  
       switch(this.type) {  
           case 'password':  
           case 'select-multiple':  
           case 'select-one':  
           case 'text':  
           case 'textarea':  
               jQuery(this).val('');  
               break;  
           case 'checkbox':  
           case 'radio':  
               this.checked = false;  
       }  
   });  

   jQuery('#wu_category').hide();
   jQuery('#wu_county').hide();
   jQuery('#wu_area').hide();

}
